const toggleEventStatusQuery = `-- name: ToggleEventStatusQuery :execrows
UPDATE event
SET event_status = (
    CASE
        WHEN event_status = 'ACTIVE'::event_status_enum THEN 'CLOSED'::event_status_enum
        ELSE 'ACTIVE'::event_status_enum
    END
)
WHERE id = $1
`

func (q *Queries) ToggleEventStatusQuery(ctx context.Context, db DBTX, id uuid.UUID) (int64, error) {
	result, err := db.Exec(ctx, toggleEventStatusQuery, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateEventQuery = `-- name: UpdateEventQuery :execrows
UPDATE event SET
  name = $2,
  blurb = $3,
  description = $4,
  cover_image_url = $5,
  price = $6,
  is_per_head = $7,
  rules = $8,
  event_type = $9,
  is_group = $10,
  max_teamsize = $11,
  min_teamsize = $12,
  total_seats = $13,
  seats_filled = $14,
  event_status = $15,
  event_mode = $16,
  attendance_mode = $17,
  is_technical = $18
WHERE id = $1
`

type UpdateEventQueryParams struct {
	ID             uuid.UUID          `json:"id"`
	Name           string             `json:"name"`
	Blurb          string             `json:"blurb"`
	Description    string             `json:"description"`
	CoverImageUrl  pgtype.Text        `json:"cover_image_url"`
	Price          pgtype.Numeric     `json:"price"`
	IsPerHead      bool               `json:"is_per_head"`
	Rules          string             `json:"rules"`
	EventType      EventTypeEnum      `json:"event_type"`
	IsGroup        bool               `json:"is_group"`
	MaxTeamsize    pgtype.Int4        `json:"max_teamsize"`
	MinTeamsize    pgtype.Int4        `json:"min_teamsize"`
	TotalSeats     int32              `json:"total_seats"`
	SeatsFilled    int32              `json:"seats_filled"`
	EventStatus    EventStatusEnum    `json:"event_status"`
	EventMode      EventModeEnum      `json:"event_mode"`
	AttendanceMode AttendanceModeEnum `json:"attendance_mode"`
	IsTechnical    pgtype.Bool        `json:"is_technical"`
}

func (q *Queries) UpdateEventQuery(ctx context.Context, db DBTX, arg UpdateEventQueryParams) (int64, error) {
	result, err := db.Exec(ctx, updateEventQuery,
		arg.ID,
		arg.Name,
		arg.Blurb,
		arg.Description,
		arg.CoverImageUrl,
		arg.Price,
		arg.IsPerHead,
		arg.Rules,
		arg.EventType,
		arg.IsGroup,
		arg.MaxTeamsize,
		arg.MinTeamsize,
		arg.TotalSeats,
		arg.SeatsFilled,
		arg.EventStatus,
		arg.EventMode,
		arg.AttendanceMode,
		arg.IsTechnical,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
